import{_ as l,l as i,o as e,c as s,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"库内死锁","description":"","frontmatter":{"title":"库内死锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-deadlock.md","filePath":"cs/db-deadlock.md","lastUpdated":1789023840000}'),h={name:"cs/db-deadlock.md"};function E(_,a,f,m,A,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="库内死锁" tabindex="-1">库内死锁 <a class="header-anchor" href="#库内死锁" aria-label="Permalink to &quot;库内死锁&quot;">​</a></h1><div class="epigraph"><p>事务锁上的等待可以成环；库检测环并回滚其中一人，与操作系统的四条件同一结构、另一套对象。</p><footer>—— 对照[死锁四个条件](/cs/deadlock-coffman)；Gray and Reuter 对等待图的整理</footer></div><p><a href="/cs/isolation-levels">上一课</a>让事务为隔离而持锁或等待版本冲突。本课不重列异常名。<a href="/cs/isolation-levels">Coffman 四条件</a>已在操作系统课钉过。缺口是：数据库的锁是数据项上的、可升级、可超时，等待图在锁管理器里，而不是进程对设备。库通常<strong>检测并牺牲</strong>，很少靠银行家算法预防。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(T_1\\) 持有 \\(x\\) 等 \\(y\\)，\\(T_2\\) 持有 \\(y\\) 等 \\(x\\)，环出现。缺口不是再证四条件，而是把对象换成事务与锁：互斥（X）、占有并等待、不可抢占（一般不抢锁）、循环等待。检测：周期建等待图或在加边时判环。牺牲：abort 代价较小或年轻的事务，其 UNDO 走<a href="/cs/aries-recovery">ARIES</a>。</p><p><span class="marginnote">闩锁（页内短锁）死锁由引擎自己保证无环或有固定顺序；事务死锁才进等待图。两者不要混成一句「数据库死锁」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>等待图：顶点事务，边「等谁」。有环则选受害者。超时是粗糙检测，可能误杀慢事务。预防：按对象序加锁、wait-die / wound-wait 时间戳，应用难守全序，故引擎以检测为主。本课不把分布式死锁的幽灵边写完，只点名：两阶段提交等待也会跨节点成环。</p>',8)),(e(),d(c,null,{default:r(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAIT%5B%22%E9%94%81%E7%AD%89%E5%BE%85%22%5D%20--%3E%20WG%5B%22%E7%AD%89%E5%BE%85%E5%9B%BE%22%5D%0A%20%20WG%20--%3E%7C%22%E6%9C%89%E7%8E%AF%22%7C%20ABRT%5B%22abort%20%E5%8F%97%E5%AE%B3%E8%80%85%22%5D%0A%20%20ABRT%20--%3E%20UNDO%5B%22WAL%20UNDO%22%5D%0A%20%20WG%20--%3E%20TPC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%B8%A4%E9%98%B6%E6%AE%B5%E6%8F%90%E4%BA%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>隔离级别影响环的频率：锁越长、粒度越粗，环越多。MVCC 减少读写等待，写写仍可环。受害者回滚释放锁，环断，其余前进；被牺牲者由应用重试，可能再次撞上热点——这是活锁边界，不是检测失败。</p><p>死锁不是完整性错误：约束仍成立，只是进度卡住。日志必须记下 abort，以免恢复把半成品重做提交。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把死锁当「锁用错了」的道德判断；可串行协议几乎必然允许等待。也不讲应用层的重试风暴治理。单对象无等待的 OCC 用中止换阻塞，死锁少、中止多，是另一权衡。</p><p>检测周期太长，吞吐先冻住；太短则空耗 CPU。这是参数，不是新协议。后课默认：单机锁死锁可检测；跨资源管理器的原子提交是另一协议，失败模式从环变成协调器阻塞。</p><p>牺牲者必须真的 abort 并释放，环才会断。只超时不 UNDO，等待图仍在。这与 OS 里杀进程同一结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>闩锁死锁由引擎内部顺序避免；事务死锁才进等待图，二者不要混名。</p></li><li><p>后课 2PC 的等待跨节点，检测图会变成分布式。</p></li><li><p>隔离带来等待；库内死锁 = 事务等待图成环，牺牲一人。</p></li><li><p>与 OS 四条件同构，对象是锁项，处理以检测为主。</p></li><li><p>跨库原子提交不能靠这一张等待图，入口是两阶段提交。</p></li><li><p>出处：Gray and Reuter；对照 Coffman et al.；Bernstein 并发控制。</p></li></ul>',9))])}const T=l(h,[["render",E]]);export{B as __pageData,T as default};
